<?php require __DIR__.'/includes/bootstrap.php';$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();if($count>0)exit('تم إنشاء المدير مسبقاً. احذف ملف setup.php من الاستضافة الآن.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$u=trim($_POST['username']??'');$p=$_POST['password']??'';if(strlen($u)<4||strlen($p)<10)$error='اجعل اسم المستخدم 4 أحرف على الأقل وكلمة المرور 10 أحرف على الأقل.';else{$s=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);header('Location: admin/login.php');exit;}}$page_title='إنشاء المدير';require __DIR__.'/includes/header.php';?><main class="container" style="max-width:500px"><div class="panel"><h1 class="gold">إنشاء حساب مدير المتجر</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>اسم المستخدم</label><input name="username" required minlength="4"></div><div class="field"><label>كلمة المرور (10 أحرف على الأقل)</label><input type="password" name="password" required minlength="10"></div><button class="btn">إنشاء حساب المدير</button></form></div></main><?php require __DIR__.'/includes/footer.php';?>
